import type { ProjectPath } from "../identifiers.js";

/** The scope a plan fragment owns in generated output. */
export enum OwnershipKind {
  /** Own every entry below one generated root path. */
  CompleteTree = "complete-tree",
  /** Own only an explicit set of generated file paths. */
  ExactFiles = "exact-files",
}

/**
 * Declares the generated paths controlled by one plan fragment.
 *
 * @example
 * ```ts
 * const ownership: Ownership = {
 *   kind: OwnershipKind.ExactFiles,
 *   paths: [createProjectPath(".external-plugin/plugin.json")],
 * };
 * ```
 */
export type Ownership =
  | {
      /** Discriminates complete-tree ownership. */
      readonly kind: OwnershipKind.CompleteTree;
      /** Root directory whose entire generated tree is owned. */
      readonly root: ProjectPath;
    }
  | {
      /** Discriminates exact-file ownership. */
      readonly kind: OwnershipKind.ExactFiles;
      /** Exact file paths that must each have zero or one desired artifact. */
      readonly paths: readonly ProjectPath[];
    };

/** The filesystem entry represented by a generated artifact. */
export enum ArtifactKind {
  /** A directory artifact without content bytes. */
  Directory = "directory",
  /** A file artifact containing generated bytes. */
  File = "file",
}

/** Description of a generated directory. */
export interface DirectoryArtifact {
  /** Discriminates directory artifacts. */
  readonly kind: ArtifactKind.Directory;
  /** Repository-relative directory path. */
  readonly path: ProjectPath;
}

/** Mutable-input form of a generated file. */
export interface FileArtifactInput {
  /** Discriminates file artifacts. */
  readonly kind: ArtifactKind.File;
  /** Repository-relative file path. */
  readonly path: ProjectPath;
  /** Bytes copied when the immutable artifact is created. */
  readonly content: Uint8Array;
}

/** Immutable generated file with defensively copied content. */
export interface FileArtifact {
  /** Discriminates file artifacts. */
  readonly kind: ArtifactKind.File;
  /** Repository-relative file path. */
  readonly path: ProjectPath;
  /** A fresh copy of the generated bytes on every read. */
  readonly content: Buffer;
}

/** Input accepted when constructing an immutable artifact. */
export type ArtifactInput = DirectoryArtifact | FileArtifactInput;
/**
 * One immutable generated directory or file.
 *
 * @example
 * ```ts
 * const artifact: Artifact = {
 *   kind: ArtifactKind.Directory,
 *   path: createProjectPath("skills"),
 * };
 * ```
 */
export type Artifact = DirectoryArtifact | FileArtifact;

/**
 * Copy and freeze one generated artifact.
 *
 * @param input - Directory description or file bytes to snapshot.
 * @returns An immutable artifact whose file bytes cannot be mutated through aliases.
 */
export function createArtifact(input: ArtifactInput): Artifact {
  if (input.kind === ArtifactKind.Directory) {
    return Object.freeze({ ...input });
  }
  const bytes = Buffer.from(input.content);
  return Object.freeze({
    kind: ArtifactKind.File,
    path: input.path,
    get content(): Buffer {
      return Buffer.from(bytes);
    },
  });
}

/**
 * Copy and freeze one ownership declaration.
 *
 * @param ownership - Ownership declaration to snapshot.
 * @returns An immutable ownership declaration with a copied exact-path list.
 */
export function createOwnership(ownership: Ownership): Ownership {
  return ownership.kind === OwnershipKind.ExactFiles
    ? Object.freeze({
        kind: ownership.kind,
        paths: Object.freeze([...ownership.paths]),
      })
    : Object.freeze({ ...ownership });
}
